import type { DevServer } from '@teambit/bundler';
import type { Server } from 'http';
import { join } from 'path';
import findRoot from 'find-root';
import { inspect } from 'util';
import objectHash from 'object-hash';
import type { Logger } from '@teambit/logger';
import type { Workspace } from '@teambit/workspace';
import type { PubsubMain } from '@teambit/pubsub';
import { EnvContext } from '@teambit/envs';
import {
  rspack as RspackCompiler,
  Configuration,
  Compiler,
} from '@rspack/core';
import {
  RspackDevServer as RspackDS,
  Configuration as DevServerConfig,
} from '@rspack/dev-server';
import {
  RspackConfigDevServerTransformContext,
  RspackConfigMutator,
  runTransformers,
  type RspackConfigTransformer,
} from '@teambit/rspack.modules.rspack-config-mutator';
import { generateTransformers } from '@teambit/rspack.rspack-bundler';
import { RspackDevServerOptions } from './rspack-dev-server-options';
import { configFactory } from './rspack.dev.config';

export interface RspackConfigWithDevServer extends Configuration {
  devServer: DevServerConfig;
}

export type DevServerAppContext = {
  logger: Logger;
  workspacePath: Workspace['path'];
  pubsub: PubsubMain;
};

type RspackDevServerAspectsContext = {
  logger: Logger;
  workspacePath: string;
  pubsub: PubsubMain;
};

export class RspackDevServer implements DevServer {
  private readonly Rspack: typeof RspackCompiler;

  private readonly RspackDS: typeof RspackDS;

  id = 'rspack-dev-server';

  displayName = 'Rspack dev server';

  constructor(
    private config: Configuration,
    private rspackModulePath: string = require.resolve('@rspack/core'),
    private rspackDevServerModulePath: string = require.resolve(
      '@rspack/dev-server'
    )
  ) {
    // eslint-disable-next-line import/no-dynamic-require, global-require
    this.Rspack = require(this.rspackModulePath);
    // eslint-disable-next-line import/no-dynamic-require, global-require
    this.RspackDS = require(this.rspackDevServerModulePath).RspackDevServer;
  }

  private getCompiler(): Compiler {
    return this.Rspack(this.config);
  }

  version(): string {
    // Resolve version from the rspack-dev-server package.json
    // TODO: this is now merged, so from next version we can take it from the
    // module itself: https://github.com/web-infra-dev/rspack/pull/7305
    try {
      const root = findRoot(this.rspackDevServerModulePath);
      const packageJsonPath = join(root, 'package.json');
      // eslint-disable-next-line import/no-dynamic-require, global-require
      const packageJson = require(packageJsonPath);
      return packageJson.version;
    } catch (err) {
      return 'unknown';
    }
  }

  displayConfig(): string {
    return inspect(this.config, { depth: 10 });
  }

  hash(): string {
    const objToHash = {
      rspack: this.rspackModulePath,
      rspackDevServer: this.rspackDevServerModulePath,
      config: this.config,
    };
    return objectHash(objToHash);
  }

  async listen(port: number): Promise<Server> {
    if (!this.config.devServer) {
      throw new Error('Missing devServer configuration for rspack');
    }
    // Prevent different port between the config port and the listen arg port
    this.config.devServer.port = port;

    // Update WebSocket URL to use the correct port for HMR
    if (
      this.config.devServer.client &&
      typeof this.config.devServer.client === 'object'
    ) {
      const cloudWS = process.env._WORKSPACE_ID || undefined;
      this.config.devServer.client.webSocketURL = {
        hostname: cloudWS
          ? `${cloudWS}p${port}.workspaces.bit.cloud`
          : '0.0.0.0',
        port: cloudWS ? 443 : port,
        pathname: '/ws',
        protocol: cloudWS ? 'https' : 'ws',
      };
    }

    // @ts-ignore in the capsules it throws an error about compatibilities issues between rspack.compiler and rspackDevServer/rspack/compiler
    const rspackDs: RspackDS = new this.RspackDS(
      this.config.devServer,
      this.getCompiler()
    );

    await rspackDs.start();

    return rspackDs.server as Server;
  }

  static from(options: RspackDevServerOptions) {
    return (context: EnvContext) => {
      const name = options.name || 'rspack-dev-server';
      const logger = context.createLogger(name);
      const workspacePath = context.getAspect<any>(
        'teambit.workspace/workspace'
      )?.path;
      const pubsub = context.getAspect<any>('teambit.harmony/pubsub');
      const aspectContext: RspackDevServerAspectsContext = {
        logger,
        workspacePath,
        pubsub,
      };
      return RspackDevServer.create(options, aspectContext);
    };
  }

  static create(
    options: RspackDevServerOptions,
    aspectContext: RspackDevServerAspectsContext
  ) {
    const { logger, workspacePath, pubsub } = aspectContext;
    const { devServerContext } = options;

    const config = configFactory(
      options.devServerContext.id,
      workspacePath,
      devServerContext.entry,
      devServerContext.rootPath,
      devServerContext.publicPath,
      pubsub,
      devServerContext.title
    );

    const configMutator = new RspackConfigMutator(config as any);
    const transformerContext: RspackConfigDevServerTransformContext =
      Object.assign(devServerContext, { mode: 'dev' as const });
    const internalTransformers = generateTransformers(
      logger,
      undefined,
      transformerContext
    );

    const afterMutation = runTransformers(
      configMutator.clone().config,
      [
        ...internalTransformers,
        ...(options.transformers || []),
      ] as RspackConfigTransformer[],
      transformerContext
    );

    const instance = new RspackDevServer(
      afterMutation as RspackConfigWithDevServer,
      options.rspackModulePath,
      options.rspackDevServerModulePath
    );

    instance.version();

    return instance;
  }
}
